import 'fastify';

declare module 'fastify' {
  interface FastifyRequest {
    /**
     * Ответ на этот запрос — страница интерфейса или её файл, а не API.
     *
     * Признак нужен потому, что заголовки безопасности у этих двух видов
     * ответов противоположны (см. staticSite.ts), а решить по одному URL
     * нельзя: `/s/:code` отдаёт то приложение человеку, то HTML с метатегами
     * боту. Поэтому отметку ставит тот обработчик, который знает, что именно
     * отдал.
     *
     * По умолчанию false: без собранного фронтенда приложение — чистое API.
     */
    isAppPage: boolean;
  }
}
